const pageBannerImages={home:'office',stationery:'catalogue-range',business:'business',government:'government-bulk',schools:'schools-packs',about:'about',contact:'contact',faq:'help',privacy:'privacy',upload:'procurement',quote:'procurement',basket:'catalogue'};
function applyPageBanner(route){const banner=main.querySelector('.catalogue-heading,.buyer-intro,.page-hero,.shop-hero');if(!banner)return;if(realProductBannerSpecs[route]){applyRealProductBanner(banner,route);return}const subject=pageBannerImages[route]||'office';banner.classList.add('page-banner');if(['business','government','schools','about'].includes(route))banner.classList.add('matched-catalogue-banner');banner.dataset.banner=subject;banner.style.setProperty('--banner-image',`url("images/${subject}-banner-v1.webp")`)}

const realProductBannerSpecs={
business:{title:'Business stationery supply',intro:'Office essentials for once-off and recurring requirements.',products:['waltons-801215','waltons-578138','waltons-21924804']},
government:{title:'Government procurement',intro:'Submit your stationery requirements for an itemised quotation.',products:['waltons-801215','waltons-801215','waltons-801215','waltons-578138','waltons-578138','waltons-21924804']},
schools:{title:'School and education stationery',intro:'Choose a grade list or submit your school’s requirements.',products:['waltons-811436','waltons-302116','waltons-204448']},
about:{title:'About Lepetse',intro:'Stationery supply for businesses, schools and government.',products:['waltons-801215','waltons-811436','waltons-578138','waltons-302116']}
};
function applyRealProductBanner(banner,route){const spec=realProductBannerSpecs[route],wrap=banner.querySelector('.wrap');if(!wrap)return;banner.classList.add('real-product-banner','matched-catalogue-banner');banner.dataset.productBanner=route;banner.querySelector('.eyebrow')?.remove();const title=wrap.querySelector('h1'),intro=wrap.querySelector('p');if(title)title.textContent=spec.title;if(intro)intro.textContent=spec.intro;wrap.classList.add('real-banner-content');const art=document.createElement('div');art.className='real-banner-products';art.setAttribute('aria-hidden','true');art.innerHTML=spec.products.map((id,i)=>{const product=products.find(p=>p.id===id);return product?`<img class="real-banner-product product-position-${i}" src="${esc(product.image)}" alt="" width="180" height="150" loading="eager">`:''}).join('');if(['business','government','schools','about'].includes(route)){banner.classList.add('branded-office-banner');if(route!=='business')banner.style.setProperty('--branded-scene',`url("images/${route}-branded-scene-v1.png")`)}else banner.append(art)}
